// Title: Cube Slicer
// Author: Claude, ItsWesSmithYo
// Project: OneManShYo

float sdBox(vec3 p, vec3 b) {
    vec3 q = abs(p) - b;
    return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}

vec3 calcNormal(vec3 p, vec3 cubePos, mat3 rot) {
    vec2 e = vec2(0.001, 0.0);
    vec3 pos = p - cubePos;
    pos = rot * pos;
    return normalize(vec3(
        sdBox(pos + e.xyy, vec3(0.2)) - sdBox(pos - e.xyy, vec3(0.2)),
        sdBox(pos + e.yxy, vec3(0.2)) - sdBox(pos - e.yxy, vec3(0.2)),
        sdBox(pos + e.yyx, vec3(0.2)) - sdBox(pos - e.yyx, vec3(0.2))
    ));
}

mat3 rotateX(float t) {
    return mat3(1.0, 0.0, 0.0,
                0.0, cos(t), -sin(t),
                0.0, sin(t), cos(t));
}

mat3 rotateY(float t) {
    return mat3(cos(t), 0.0, sin(t),
                0.0, 1.0, 0.0,
                -sin(t), 0.0, cos(t));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord/iResolution.xy;
    uv.x *= iResolution.x/iResolution.y;
    uv = uv * 2.0 - 1.0;

    vec3 orbit = vec3(
        sin(iTime * 0.8) * 0.7,
        sin(iTime * 1.2) * 1.0,
        cos(iTime * 0.6) * 0.5
    );

    vec3 ro = vec3(0.0, 0.0, -3.0);
    vec3 rd = normalize(vec3(uv, 1.0));
    vec3 lightPos = vec3(2.0, 2.0, -2.0);

    vec3 cubePos = orbit;
    mat3 rot = rotateX(iTime) * rotateY(iTime * 0.7);

    // Raymarch cube
    float cube = 0.0;
    vec3 hitPos = ro;
    vec3 p = ro;

    for(int i = 0; i < 64; i++) {
        vec3 pos = p - cubePos;
        pos = rot * pos;
        float d = sdBox(pos, vec3(0.2));
        if(d < 0.001) {
            cube = 1.0;
            hitPos = p;
            break;
        }
        p += rd * d;
        if(length(p - ro) > 5.0) break;
    }

    // Calculate cube lighting
    vec3 cubeColor = vec3(0.0);
    if(cube > 0.0) {
        vec3 N = calcNormal(hitPos, cubePos, rot);
        vec3 L = normalize(lightPos - hitPos);
        vec3 V = normalize(ro - hitPos);
        vec3 R = reflect(-L, N);

        float ambient = 0.1;
        float diffuse = max(dot(N, L), 0.0);
        float specular = pow(max(dot(R, V), 0.0), 32.0);

        cubeColor = vec3(1.0) * (ambient + diffuse * 0.7 + specular * 0.3);
    }

    // Draw lines
    vec3 lineColor = vec3(0.0);
    for(int i = 0; i < 3; i++) {
        float t = iTime * (0.3 + float(i) * 0.4) + float(i) * 2.0;
        vec2 p = uv;
        p = vec2(p.x * cos(t) - p.y * sin(t), p.x * sin(t) + p.y * cos(t));
        float line = smoothstep(0.02, 0.01, abs(p.x));
        if(cube > 0.0 && hitPos.y > cubePos.y) {
            line *= 0.0;
        }
        lineColor = max(lineColor, vec3(line));
    }

    fragColor = vec4(max(cubeColor, lineColor), 1.0);
}
